using System.Text.Json;

var options = new JsonSerializerOptions
{
    WriteIndented = true,
    PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
};
var settings = new AppSettings("dark", 14, ["csharp", "json"]);

string json = JsonSerializer.Serialize(settings, options);
Console.WriteLine(json);
File.WriteAllText("settings.json", json);

AppSettings? loaded = JsonSerializer.Deserialize<AppSettings>(File.ReadAllText("settings.json"), options);
Console.WriteLine(loaded?.FontSize);
Console.WriteLine(loaded?.Tags.Length);
Console.WriteLine(loaded?.Theme == settings.Theme);

record AppSettings(string Theme, int FontSize, string[] Tags);

using System.Text.Json.Nodes;

string payload = """
    { "name": "Ada", "languages": ["C#", "F#"], "active": true, "age": null }
    """;

JsonNode root = JsonNode.Parse(payload)!;

Console.WriteLine(root["name"]!.GetValue<string>());
Console.WriteLine(root["languages"]![1]!.GetValue<string>());
Console.WriteLine(root["active"]!.GetValue<bool>());
Console.WriteLine(root["age"] is null);
Console.WriteLine(root["languages"]!.AsArray().Count);
